const rl = require("readline").createInterface({ input: process.stdin });
var iter = rl[Symbol.asyncIterator]();
const readline = async () => (await iter.next()).value;

void (async function () {
  const n = parseInt(await readline());

  const relations = [];
  for (let i = 0; i < n - 1; i++) {
    relations.push((await readline()).split(" ").map(Number));
  }

  console.log(getMinDP(relations, n));
})();

function getMinDP(relations, n) {
  // minDp用于保存最小城市聚集度
  let minDp = Infinity;
  // city用于保存最小城市聚集度对应的被切割的城市序号
  let city = [];

  // 遍历每个城市 1~n
  for (let i = 1; i <= n; i++) {
    // 利用并查集对城市进行关联
    const ufs = new UnionFindSet(n + 1);

    for (let [x, y] of relations) {
      // 切断城市的所有道路，即忽略和城市i有联系的合并操作
      if (x === i || y === i) continue;
      // 否则连接x和y
      ufs.union(x, y);
    }

    // 统计各个连通分量自身的城市个数
    const cnts = new Array(n + 1).fill(0);
    for (let j = 1; j <= n; j++) {
      const fa = ufs.find(j);
      cnts[fa]++;
    }

    // 取最多城市个数作为当前的切断城市的聚集度
    const dp = Math.max(...cnts);

    if (dp < minDp) {
      minDp = dp;
      city = [i];
    } else if (dp === minDp) {
      city.push(i);
    }
  }

  // 如果有多个，按照编号升序输出。
  city.sort((a, b) => a - b);
  return city.join(" ");
}

