#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

/** 并查集定义 **/
typedef struct {
    int *fa;
} UFS;

UFS *new_UFS(int n) {
    UFS *ufs = (UFS *) malloc(sizeof(UFS));

    ufs->fa = (int *) malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        ufs->fa[i] = i;
    }

    return ufs;
}

int find_UFS(UFS *ufs, int x) {
    if (x != ufs->fa[x]) {
        ufs->fa[x] = find_UFS(ufs, ufs->fa[x]);
        return ufs->fa[x];
    }
    return x;
}

void union_UFS(UFS *ufs, int x, int y) {
    int x_fa = find_UFS(ufs, x);
    int y_fa = find_UFS(ufs, y);

    if (x_fa != y_fa) {
        ufs->fa[y_fa] = x_fa;
    }
}

int cmp(const void *a, const void *b) {
    return (*(int *) a) - (*(int *) b);
}

/**   算法入口   **/
int main() {
    int n;
    scanf("%d", &n);

    int relations[n - 1][2];
    for (int i = 0; i < n - 1; i++) {
        scanf("%d %d", &relations[i][0], &relations[i][1]);
    }

    // 记录最小dpi
    int minDp = INT_MAX;

    // 记录最小dpi对应的切断城市
    int city[n];
    int city_size = 0;

    // i 是被切断城市
    for (int i = 1; i <= n; i++) {
        // 利用并查集对城市进行关联
        UFS *ufs = new_UFS(n + 1);

        for (int j = 0; j < n - 1; j++) {
            int x = relations[j][0];
            int y = relations[j][1];

            // 如果x或y是被切断城市，则对应连接关系不成立
            if (x == i || y == i) continue;

            // 否则连接x和y
            union_UFS(ufs, x, y);
        }

        // cnts记录每个根（每个节点都能当成一个根来看）下的城市个数
        int cnts[n + 1];
        for (int k = 0; k <= n; k++) {
            cnts[k] = 0;
        }

        for (int k = 1; k <= n; k++) {
            // 对k=1~n每个城市找根fa
            int fa = find_UFS(ufs, k);
            // 根fa下的子城市个数++
            cnts[fa]++;
        }

        // cnts的最大值即最大城市群大小
        int dp = cnts[1];
        for (int k = 2; k <= n; k++) {
            if (cnts[k] > dp) {
                dp = cnts[k];
            }
        }

        // 和minDp比较，保留最小值
        if (dp < minDp) {
            minDp = dp;
            city_size = 0;
            city[city_size++] = i;
        } else if (dp == minDp) {
            city[city_size++] = i;
        }
    }

    // 如果有多个，按照编号升序输出。
    qsort(city, city_size, sizeof(int), cmp);

    for (int i = 0; i < city_size; i++) {
        printf("%d", city[i]);
        if (i != city_size - 1) {
            printf(" ");
        }
    }

    return 0;
}
